        public async Task<IActionResult> Import()
        {
            var req = new RoadInfrastructureDetectionRequest();
            req.Type = PotholeType.AsphaltCrack;
            req.Diameter = null;
            req.Depth = null;
            req.Lat = 44.40843f;
            req.Lng = 26.14033f;
            req.ReportingDate = new DateTime(2024, 08, 04, 13, 21, 16);
            req.Severity = SeverityType.Medium;
            var fileUrl = $"https://portal.newto.tech/assetsimg/" + "6.jpg";

            req.NeedIntervention = YesNo.Yes;
            req.EdgeId = Guid.Parse("b3b3b3b3-3b3b-3b3b-3b3b-3b3b3b3b3b3b");
            req.Description = "Fisuri multiple în asfalt pe banda de circulație, necesită reparație pentru a preveni extinderea și deteriorarea suplimentară.";





            req.ResolutionStatus = DetectionResolutionStatus.Reported;

            req.Files = new List<CreateFileIn>();
            var file = new CreateFileIn()
            {
                Category = "RoadInfrastructureDetection",
                ContentType = "image/jpeg",
                FileName = "aaa.jpg",


            };

            using (var webClient = new WebClient())
            {
                file.File = webClient.DownloadData(fileUrl);
            }
            req.Files.Add(file);


            await _potholeDetectionService.CreateRoadInfrastructureDetectionAsync(req);



            return Ok();
        }



        public async Task<IActionResult> PieChart()
        {
            var model = new PieChartModel();
            model.chart.type = "donut";
            model.chart.width = 380;
            model.series = new List<int> { 44, 55, 13, 33 };
            model.labels = new List<string> { "Apple", "Mango", "Orange", "Watermelon" };
            model.colors = new List<string> { "#FF5733", "#FFC300", "#FF5733", "#FFC300" };



            model.dataLabels.enabled = false;


            model.responsive.Add(new Responsive()
            {
                breakpoint = 480,
                options = new Options()
                {
                    chart = new Chart()
                    {
                        width = 200
                    },
                    legend = new Legend()
                    {
                        show = false
                    }
                }
            });
            model.legend.show = true;
            model.legend.position = "right";
            model.legend.offsetY = 0;
            model.legend.height = 230;
            model.legend.horizontalAlign = "right";
            model.title.text = "Donut Chart";




            return View("Views/Charts/PieChart.cshtml", model);
        }







